 */
export function getPerformanceThresholdDescription(payloadSize: number): string {
  const sizeKb = payloadSize / 1024;

  if (sizeKb <= PERFORMANCE_THRESHOLDS.SMALL.sizeKb) {
    return PERFORMANCE_THRESHOLDS.SMALL.description;
  } else if (sizeKb <= PERFORMANCE_THRESHOLDS.MEDIUM.sizeKb) {
    return PERFORMANCE_THRESHOLDS.MEDIUM.description;
  } else {
    return PERFORMANCE_THRESHOLDS.LARGE.description;
  }
}

/**
 * Calculate percentile from array of durations
 * Useful for tracking 95th percentile performance
 * @param durations Array of durations in milliseconds
 * @param percentile Percentile to calculate (0-100)
 * @returns Duration at the percentile
 */
export function calculatePercentile(durations: number[], percentile: number): number {
  if (durations.length === 0) {
    return 0;
  }

  const sorted = [...durations].sort((a, b) => a - b);
  const index = Math.ceil((percentile / 100) * sorted.length) - 1;
  return sorted[Math.max(0, index)];
}

/**
 * Calculate average duration from array
 * @param durations Array of durations in milliseconds
 * @returns Average duration
 */
export function calculateAverageDuration(durations: number[]): number {
  if (durations.length === 0) {
    return 0;
  }

  const sum = durations.reduce((acc, val) => acc + val, 0);
  return sum / durations.length;
}

/**
 * Get all performance thresholds
 */
export function getPerformanceThresholds() {
  return PERFORMANCE_THRESHOLDS;
}
