 * Unit tests for performance-monitor utility
 */

import { describe, it, expect, beforeEach } from 'vitest';
import {
  startPerformanceTimer,
  endPerformanceTimer,
  validatePerformance,
  getPerformanceThresholdDescription,
  calculatePercentile,
  calculateAverageDuration,
  getPerformanceThresholds
} from '../../../src/translation/utils/performance-monitor.js';

describe('Performance Monitor Utility', () => {
  describe('Performance timing', () => {
    it('should measure performance with nanosecond precision', () => {
      const start = startPerformanceTimer();

      // Small delay to make timing measurable
      const end = process.hrtime.bigint();
      const sum = Array.from({ length: 1000 }, (_, i) => i).reduce((a, b) => a + b);

      const metrics = endPerformanceTimer(start);

      expect(metrics.duration_ms).toBeGreaterThanOrEqual(0);
      expect(metrics.durationNs).toBeGreaterThanOrEqual(0n);
      expect(metrics.startTime).toBeLessThanOrEqual(metrics.endTime);
    });

    it('should return proper PerformanceMetrics structure', () => {
      const start = startPerformanceTimer();
      const metrics = endPerformanceTimer(start);

      expect(metrics).toHaveProperty('duration_ms');
      expect(metrics).toHaveProperty('durationNs');
      expect(metrics).toHaveProperty('startTime');
      expect(metrics).toHaveProperty('endTime');
      expect(typeof metrics.duration_ms).toBe('number');
      expect(typeof metrics.durationNs).toBe('bigint');
    });
  });

  describe('validatePerformance', () => {
    it('should validate small request performance (<1KB)', () => {
      const result = validatePerformance(1, 512); // 1ms for 512 bytes

      expect(result.isValid).toBe(true);
      expect(result.category).toBe('small');
      expect(result.threshold_ms).toBe(2);
    });

    it('should validate medium request performance (10KB)', () => {
      const result = validatePerformance(4, 10 * 1024); // 4ms for 10KB

      expect(result.isValid).toBe(true);
      expect(result.category).toBe('medium');
      expect(result.threshold_ms).toBe(5);
    });

    it('should validate large request performance (100KB)', () => {
      const result = validatePerformance(8, 100 * 1024); // 8ms for 100KB

      expect(result.isValid).toBe(true);
      expect(result.category).toBe('large');
      expect(result.threshold_ms).toBe(10);
    });

    it('should flag performance violations', () => {
      const result = validatePerformance(20, 100 * 1024); // 20ms for 100KB (over 10ms threshold)

      expect(result.isValid).toBe(false);
      expect(result.category).toBe('large');
    });

    it('should return complete validation result', () => {
      const result = validatePerformance(3, 5 * 1024);

      expect(result).toHaveProperty('isValid');
      expect(result).toHaveProperty('threshold_ms');
      expect(result).toHaveProperty('actual_ms');
      expect(result).toHaveProperty('payloadSize');
      expect(result).toHaveProperty('category');
    });
  });

  describe('getPerformanceThresholdDescription', () => {
    it('should return description for small request', () => {
      const desc = getPerformanceThresholdDescription(512);
      expect(desc).toContain('Small');
      expect(desc).toContain('1KB');
    });

    it('should return description for medium request', () => {
      const desc = getPerformanceThresholdDescription(10 * 1024);
      expect(desc).toContain('Medium');
      expect(desc).toContain('10KB');
    });"}

